class _AsyncPool:
    """``pool`` commands."""

    def __init__(self, t: _AsyncTransport) -> None:
        self._t = t

    async def new(
        self,
        name: str,
        *,
        cpus: int | None = None,
        max_vms: int | None = None,
        region: str | None = None,
    ) -> Any:
        """Create a pool: reserved capacity for your team's VMs.

        CLI: ``pool new <name> --cpus=N [--region=<region>] [--max-vms=M]``

        Args:
            cpus: number of CPUs reserved for the pool (required; an even number of
                vCPUs from 2 through 512 (2, 4, 6, and so on; memory is 2 GiB per vCPU))
            max_vms: maximum VMs in the pool (Work defaults to the size limit of up to
                25 VMs per vCPU, capped at 1000 VMs) (server default: 100)
            region: region code for the pool (required unless your team has dedicated
                hosts, which decide the region)
        """
        return await self._t.call(
            "pool new",
            [name],
            [
                ("cpus", "number", cpus),
                ("max-vms", "number", max_vms),
                ("region", "string", region),
            ],
        )

    async def hosts(self) -> Any:
        """Show your team's dedicated hosts, where its new pools are placed.

        CLI: ``pool hosts``
        """
        return await self._t.call("pool hosts", [])

    async def list(self, pool_name: str | None = None, *, range: str | None = None, usage: bool = False) -> Any:
        """List your team's pools, or show live or historical usage with --usage.

        CLI: ``pool list [pool-name] [--usage [--range=live|24h|7d|30d]]``

        Args:
            range: statistics range: live, 24h, 7d, or 30d (requires --usage) (server
                default: live)
            usage: show live or historical CPU and starvation statistics
        """
        return await self._t.call(
            "pool list",
            [pool_name],
            [("range", "string", range), ("usage", "bool", usage or None)],
        )

    async def adopt(self, *, pool: str | None = None, vm: str | None = None) -> Any:
        """Adopt a VM into a pool; this can take several minutes.

        CLI: ``pool adopt --vm=<vm-name> --pool=<pool-name>``

        Args:
            pool: pool to adopt into (required)
            vm: VM to adopt (required)
        """
        return await self._t.call("pool adopt", [], [("pool", "string", pool), ("vm", "string", vm)])

    async def detach(self, *, poolless: bool = False, vm: str | None = None) -> Any:
        """Detach a VM from its pool into its own standalone capacity (--poolless leaves it outside any pool).

        CLI: ``pool detach --vm=<vm-name> [--poolless]``

        Args:
            poolless: leave the VM outside any pool instead of making it standalone
                (only while your team has poolless VMs)
            vm: VM to detach from its pool (required)
        """
        return await self._t.call(
            "pool detach",
            [],
            [("poolless", "bool", poolless or None), ("vm", "string", vm)],
        )

    async def resize(
        self,
        *args: str,
        cpus: int | None = None,
        force: bool = False,
        max_vms: str | None = None,
    ) -> Any:
        """Change a pool's CPU capacity or VM cap.

        CLI: ``pool resize <name> --cpus=N | pool resize <name> --max-vms=N [--force]``

        Args:
            cpus: new pool size in vCPUs (required unless --max-vms is set; even, from 2
                up to the placement limit)
            force: allow --max-vms below the current VM count (does not stop or evict
                VMs)
            max_vms: maximum VMs in the pool (Work: at most 25 per vCPU, up to 1000)
        """
        return await self._t.call(
            "pool resize",
            [args],
            [
                ("cpus", "number", cpus),
                ("force", "bool", force or None),
                ("max-vms", "string", max_vms),
            ],
        )

    async def rename(self, old_name: str, new_name: str) -> Any:
        """Rename a pool without changing its capacity or VMs.

        CLI: ``pool rename <old-name> <new-name>``
        """
        return await self._t.call("pool rename", [old_name, new_name])

    async def delete(self, name: str) -> Any:
        """Delete a pool (refused while it has VMs; --force detaches them).

        CLI: ``pool delete <name> [--force]``
        """
        return await self._t.call("pool delete", [name])


